use clap::{Command, Arg, ArgAction, value_parser};
use clap_complete::{generate, shells::*};
use std::path::{Path, PathBuf};

fn cli() -> Command {
    Command::new("tree-sitter")
        .version("0.27.0")
        .author("Max Brunsfeld <maxbrunsfeld@gmail.com>\nAmaan Qureshi <amaanq12@gmail.com>")
        .about("Generates and tests parsers")
        .subcommand_required(true)
        .arg_required_else_help(false)
        .subcommand(
            Command::new("init-config")
                .about("Generate a default config file")
        )
        .subcommand(
            Command::new("init")
                .about("Initialize a grammar repository")
                .arg(Arg::new("update").short('u').long("update").action(ArgAction::SetTrue).help("Update outdated files"))
                .arg(Arg::new("grammar-path").short('p').long("grammar-path").value_name("GRAMMAR_PATH").help("The path to the tree-sitter grammar directory"))
        )
}

fn main() {
    let m = cli().get_matches();
    match m.subcommand() {
        Some(("init-config", _)) => {
            println!("init-config");
        }
        Some(("init", _)) => {
            println!("init");
        }
        _ => {}
    }
}
