fn verify_version(s: &str) -> Result<String, String> {
    match s.parse::<semver::Version>() {
        Ok(_) => Ok(s.to_string()),
        Err(e) => Err(e.to_string()),
    }
}

fn main() {
    let matches = cli().get_matches();
    match matches.subcommand() {
        Some(("complete", sub)) => {
            let shell = sub.get_one::<String>("shell").unwrap().as_str();
            let mut cmd = cli();
            match shell {
                "bash" => clap_complete::generate(clap_complete::shells::Bash, &mut cmd, "tree-sitter", &mut std::io::stdout()),
                "elvish" => clap_complete::generate(clap_complete::shells::Elvish, &mut cmd, "tree-sitter", &mut std::io::stdout()),
                "fish" => clap_complete::generate(clap_complete::shells::Fish, &mut cmd, "tree-sitter", &mut std::io::stdout()),
                "power-shell" => clap_complete::generate(clap_complete::shells::PowerShell, &mut cmd, "tree-sitter", &mut std::io::stdout()),
                "zsh" => clap_complete::generate(clap_complete::shells::Zsh, &mut cmd, "tree-sitter", &mut std::io::stdout()),
                "nushell" => clap_complete::generate(clap_complete::shells::Nushell, &mut cmd, "tree-sitter", &mut std::io::stdout()),
                _ => unreachable!(),
            }
        }
        _ => {}
    }
}
