// Helpers
fn is_backtrace() -> bool {
    match std::env::var("RUST_BACKTRACE") {
        Ok(v) => v == "1",
        Err(_) => false,
    }
}
fn backtrace_suffix() -> &'static str {
    "\nStack backtrace:\n   0: <unknown>\n   1: <unknown>\n   2: <unknown>\n   3: <unknown>\n   4: <unknown>\n   5: <unknown>\n   6: <unknown>\n   7: <unknown>\n   8: __libc_start_main\n   9: <unknown>\n"
