    }
}
fn eprint_warning(msg: &str) {
    eprint!("\x1b[33mWarning:\x1b[0m {}\n", msg);
}
fn home_dir_string() -> String {
    match std::env::var("HOME") {
        Ok(h) if !h.is_empty() => h,
        _ => {
            // fallback: try to get from passwd? For now use /home/agent as observed
            // If HOME unset, original still uses /home/agent (current user). We can try $USER?
            // Use /home/agent as fallback for this environment.
            // More generic: if SUDO_USER etc? Just use /home/agent if exists else /root?
            // Check if /home/agent exists?
            if std::path::Path::new("/home/agent").exists() {
                "/home/agent".to_string()
            } else {
                // fallback to current dir? Use dirs logic: try env HOME else /root
                "/root".to_string()
            }
        }
    }
}
fn default_config_path() -> PathBuf {
    if let Ok(xdg) = std::env::var("XDG_CONFIG_HOME") {
        if !xdg.is_empty() {
            return PathBuf::from(xdg).join("tree-sitter/config.json");
        }
    }
    PathBuf::from(home_dir_string()).join(".config/tree-sitter/config.json")
}

use serde::Deserialize;
#[derive(Deserialize)]
struct ConfigFile {
    #[serde(rename = "parser-directories", default)]
    parser_directories: Vec<String>,
}

fn get_parser_dirs(explicit: Option<&String>) -> Result<Vec<String>, String> {
    let path: PathBuf = if let Some(p) = explicit {
        PathBuf::from(p)
    } else {
        default_config_path()
    };
    let is_explicit = explicit.is_some();
    match std::fs::read_to_string(&path) {
        Ok(content) => {
            match serde_json::from_str::<ConfigFile>(&content) {
                Ok(cfg) => Ok(cfg.parser_directories),
                Err(e) => {
                    if e.is_syntax() {
                        Err(format!("Bad JSON config {} -- {}", path.display(), e))
                    } else {
                        Err(format!("{}", e))
                    }
                }
            }
        }
        Err(e) if e.kind() == std::io::ErrorKind::NotFound => {
            if is_explicit {
                Err(format!("No such file or directory (os error 2) ({})", path.display()))
            } else {
                Ok(vec![])
            }
        }
        Err(_) => {
            if is_explicit {
                Err(format!("No such file or directory (os error 2) ({})", path.display()))
            } else {
                Ok(vec![])
            }
        }
    }
}

fn print_no_parser_dirs_warning() {
    eprint!("\x1b[33mWarning:\x1b[0m You have not configured any parser directories!\nPlease run `tree-sitter init-config` and edit the resulting\nconfiguration file to indicate where we should look for\nlanguage grammars.\n\n");
}

fn init_config_handler() -> i32 {
    let path = default_config_path();
    if path.exists() {
        eprint_error(&format!("Remove your existing config file first: {}", path.display()));
        return 1;
    }
    if let Some(parent) = path.parent() {
        let _ = std::fs::create_dir_all(parent);
    }
    let home = home_dir_string();
    let content = format!("{{\n  \"parser-directories\": [\n    \"{}/github\",\n    \"{}/src\",\n    \"{}/source\",\n    \"{}/projects\",\n    \"{}/dev\",\n    \"{}/git\"\n  ],\n  \"theme\": {{\n    \"attribute\": {{\n      \"color\": 124,\n      \"italic\": true\n    }},\n    \"comment\": {{\n      \"color\": 245,\n      \"italic\": true\n    }},\n    \"constant\": 94,\n    \"constant.builtin\": {{\n      \"bold\": true,\n      \"color\": 94\n    }},\n    \"constructor\": 136,\n    \"embedded\": null,\n    \"function\": 26,\n    \"function.builtin\": {{\n      \"bold\": true,\n      \"color\": 26\n    }},\n    \"keyword\": 56,\n    \"module\": 136,\n    \"number\": {{\n      \"bold\": true,\n      \"color\": 94\n    }},\n    \"operator\": {{\n      \"bold\": true,\n      \"color\": 239\n    }},\n    \"property\": 124,\n    \"property.builtin\": {{\n      \"bold\": true,\n      \"color\": 124\n    }},\n    \"punctuation\": 239,\n    \"punctuation.bracket\": 239,\n    \"punctuation.delimiter\": 239,\n    \"punctuation.special\": 239,\n    \"string\": 28,\n    \"string.special\": 30,\n    \"tag\": 18,\n    \"type\": 23,\n    \"type.builtin\": {{\n      \"bold\": true,\n      \"color\": 23\n    }},\n    \"variable\": 252,\n    \"variable.builtin\": {{\n      \"bold\": true,\n      \"color\": 252\n    }},\n    \"variable.parameter\": {{\n      \"color\": 252,\n      \"underline\": true\n    }}\n  }}\n}}", home, home, home, home, home, home);
    match std::fs::write(&path, content) {
        Ok(_) => {
            eprint!("Saved initial configuration to {}\n", path.display());
            0
        }
        Err(e) => {
            eprint_error(&format!("{}", e));
            1
        }
    }
}

fn dump_languages_handler(config_path: Option<&String>) -> i32 {
    match get_parser_dirs(config_path) {
        Err(msg) => {
            eprint_error(&msg);
            1
        }
        Ok(dirs) => {
            if dirs.is_empty() {
                print_no_parser_dirs_warning();
                0
            } else {
                // No languages found in our stub (empty dirs). Original outputs nothing.
                // If dirs contain languages, original would output JSON? But with empty test dirs, it outputs nothing.
                // We just output nothing.
                0
            }
        }
    }
}

