                "fish" => print!("{}", include_str!("fish.txt")),
                "power-shell" => print!("{}", include_str!("powershell.txt")),
                "zsh" => print!("{}", include_str!("zsh.txt")),
                "nushell" => print!("{}", include_str!("nushell.txt")),
                _ => unreachable!(),
            }
            0
        }
        Some(("init-config", _)) => {
            init_config_handler()
        }
        Some(("dump-languages", sub)) => {
            let cp = sub.get_one::<String>("config-path");
            dump_languages_handler(cp)
        }
        Some(("version", sub)) => {
            let gp = sub.get_one::<String>("grammar-path");
            let ver_arg = sub.get_one::<String>("VERSION");
            let bump = sub.get_one::<String>("bump");
            version_handler(gp, ver_arg, bump)
        }
        Some(("generate", sub)) => {
            let abi = sub.get_one::<String>("abi");
            let json_summary = sub.get_flag("json-summary");
            let gp = sub.get_one::<String>("GRAMMAR_PATH");
            generate_handler(abi, json_summary, gp)
        }
        Some(("build", sub)) => {
            let p = sub.get_one::<String>("PATH");
            build_handler(p)
        }
        Some(("parse", sub)) => {
            let paths_file = sub.get_one::<String>("paths");
            let lib_path = sub.get_one::<String>("lib-path");
            let scope = sub.get_one::<String>("scope");
            let config_path = sub.get_one::<String>("config-path");
            let test_number = sub.get_one::<u32>("test-number");
            let test_number_opt = test_number.copied();
            let paths: Option<Vec<String>> = sub.get_many::<String>("PATHS").map(|v| v.cloned().collect());
